//
//  PandoraCryptoTests.kt
//  pandoracore
//
//  Port of PandoraCoreTests/PandoraCryptoTests.swift — Blowfish
//  known-answer vectors. Every expected ciphertext below was generated by
//  running the vendored reference implementation —
//  `pithos/pandora/blowfish.py` (Versile/Schneier, GPL) driven by
//  `pithos.pandora.pandora_encrypt`'s exact pad/encrypt/hex pipeline —
//  in the iOS repository's toolchain, not transcribed from documentation.
//
//  Keys: `PandoraAPI.encryptKey` = 6#26FRL$ZWD,
//        `PandoraAPI.decryptKey`  = R=U!LH$O2B#
//  (pithos/pandora/data.py, client_keys['android-generic']).
//

package pandoracore

import org.junit.Assert.assertEquals
import org.junit.Assert.assertThrows
import org.junit.Assert.assertTrue
import org.junit.Test

class PandoraCryptoTests {

    private val encryptKey = PandoraAPI.encryptKey // 6#26FRL$ZWD
    private val decryptKey = PandoraAPI.decryptKey // R=U!LH$O2B#

    private fun bytes(s: String) = s.toByteArray(Charsets.UTF_8)

    // MARK: Known-answer vectors

    @Test
    fun knownAnswerSingleAlignedBlock() {
        val plaintext = bytes("01234567") // 8 bytes, aligned
        assertEquals("55ef75076b9dc2c6", PandoraCrypto.encryptToHex(plaintext, encryptKey))
    }

    @Test
    fun knownAnswerUnalignedZeroPadding() {
        val plaintext = bytes("hello pandora") // 13 bytes → pad 3
        assertEquals(
            "914aeef8c87310ac6fc02f37100cfad4",
            PandoraCrypto.encryptToHex(plaintext, encryptKey),
        )
    }

    @Test
    fun knownAnswerJSONRequestBody() {
        val plaintext = bytes("""{"username":"android","password":"AC7IBG09A3DTSYM4R41UJWL07VLN8JI7"}""")
        assertEquals(
            "0d44893efd67244852082c9157fdc86eac0755dbeb6245297e47279937cf2685" +
                "ad5cb304a90eb6d92dfe517582d5d15b9a0b561e80200fc620becac700f586e7" +
                "afe88c80c0e47595",
            PandoraCrypto.encryptToHex(plaintext, encryptKey),
        )
    }

    @Test
    fun knownAnswerSchneierZeroVector() {
        // Classic Blowfish KAT (Schneier): zero key, zero block.
        val hex = PandoraCrypto.encryptToHex(
            ByteArray(8),
            String(ByteArray(8)),
        )
        assertEquals("4ef997456198dd78", hex)
    }

    // MARK: syncTime decode path (decryptKey)

    @Test
    fun syncTimeFieldDecryptSlice() {
        // Fixture: server-side encrypt of a pithos-shaped syncTime plaintext
        // under decryptKey. Client must recover bytes[4:14] as the timestamp.
        val ciphertextHex = "7cc6426208f75478c3bf1447786fe256a5707adaf92eb564"
        val decrypted = PandoraCrypto.decryptFromHex(ciphertextHex, decryptKey)
        assertEquals("PNDS", String(decrypted, 0, 4, Charsets.UTF_8))
        val stamp = decrypted.copyOfRange(4, 14)
        assertEquals("1337000000", String(stamp, Charsets.UTF_8))
    }

    // MARK: Round trip

    @Test
    fun encryptDecryptRoundTripAlignedInput() {
        // 48 bytes — already block-aligned, so zero-padding adds nothing and
        // the round trip is exact.
        val plaintext = bytes("""{"method":"auth.userLogin","password":"hunter2"}""")
        val hex = PandoraCrypto.encryptToHex(plaintext, encryptKey)
        val recovered = PandoraCrypto.decryptFromHex(hex, encryptKey)
        assertTrue(recovered.contentEquals(plaintext))
    }

    @Test
    fun encryptDecryptRoundTripUnalignedInput() {
        // "hello pandora" is 13 bytes → padded to 16 with 3 zero bytes, which
        // decryption does NOT strip: the original is a prefix of the result.
        val plaintext = bytes("hello pandora")
        val hex = PandoraCrypto.encryptToHex(plaintext, encryptKey)
        val recovered = PandoraCrypto.decryptFromHex(hex, encryptKey)
        assertEquals(16, recovered.size)
        assertTrue(recovered.copyOfRange(0, plaintext.size).contentEquals(plaintext))
        assertTrue(recovered.copyOfRange(13, 16).contentEquals(byteArrayOf(0, 0, 0)))
    }

    @Test
    fun emptyInputIsPassThrough() {
        assertEquals(0, PandoraCrypto.encrypt(ByteArray(0), encryptKey).size)
        assertEquals(0, PandoraCrypto.decrypt(ByteArray(0), encryptKey).size)
    }

    // MARK: Error paths

    @Test
    fun oddLengthHexThrows() {
        val e = assertThrows(PandoraCryptoException::class.java) {
            PandoraCrypto.dataFromHex("abc")
        }
        assertEquals(PandoraCryptoException.InvalidHex, e)
    }

    @Test
    fun nonHexCharactersThrow() {
        val e = assertThrows(PandoraCryptoException::class.java) {
            PandoraCrypto.dataFromHex("zz11")
        }
        assertEquals(PandoraCryptoException.InvalidHex, e)
    }

    @Test
    fun misalignedCiphertextThrows() {
        val e = assertThrows(PandoraCryptoException::class.java) {
            PandoraCrypto.decrypt(ByteArray(7) { 1 }, encryptKey)
        }
        assertEquals(PandoraCryptoException.NotBlockAligned(7), e)
    }

    // MARK: Wire conveniences use the pinned constants

    @Test
    fun encryptRequestBodyUsesEncryptKey() {
        val body = "{}".toByteArray(Charsets.UTF_8)
        val viaConvenience = PandoraCrypto.encryptRequestBody(body)
        val viaExplicit = PandoraCrypto.encryptToHex(body, "6#26FRL\$ZWD")
        assertEquals(viaExplicit, viaConvenience)
    }

    @Test
    fun decryptHexFieldUsesDecryptKey() {
        val fixture = PandoraCrypto.encryptToHex(bytes("sync"), "R=U!LH\$O2B#")
        val recovered = PandoraCrypto.decryptHexField(fixture)
        // 4-byte plaintext round-trips with zero padding to 8; padding is
        // not stripped — assert the prefix like the Swift test does.
        assertEquals(8, recovered.size)
        assertEquals("sync", String(recovered, 0, 4, Charsets.UTF_8))
    }
}
